'use client';

// ReleaseSummary: render-only view of GET /api/v2/ui/release/{run_id}.
// Every string on screen is generated by backend/eval/plainlang.py +
// backend/eval/viewmodel.py; this component fetches through the
// existing /api/play proxy and renders. No logic, no new deps.

import { useEffect, useState } from 'react';
import { ArrowDownToLine, Copy, Printer } from 'lucide-react';
import { apiRequest } from '@/lib/workspace';
import { downloadJson } from '@/lib/demo';

type Chip = { label: string; kind: string };
type Reason = { gate: string; band: string; plain_text: string; evidence_ref: string };
type Delta = {
  gate: string; band_from: string | null; band_to: string;
  delta: number | null; regression: boolean;
};
type ReleaseView = {
  run_id: string; verdict: string; verdict_plain: string; headline: string;
  scope: string; reasons: Reason[]; what_would_change: { gate: string; move: string }[];
  chips: Chip[]; compare_id: string | null; deltas: Delta[];
  offline_verify: { command: string; hash: string | null };
  odd: string | null; model_hash: string | null;
};
type ViewState =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; view: ReleaseView };

function isView(data: unknown): data is ReleaseView {
  if (typeof data !== 'object' || data === null) return false;
  const v = data as Record<string, unknown>;
  return typeof v.run_id === 'string' && typeof v.verdict === 'string'
    && typeof v.verdict_plain === 'string' && typeof v.headline === 'string'
    && (typeof v.model_hash === 'string' || v.model_hash === null) && Array.isArray(v.reasons)
    && Array.isArray(v.chips) && Array.isArray(v.deltas)
    && Array.isArray(v.what_would_change)
    && typeof v.offline_verify === 'object' && v.offline_verify !== null;
}

function verdictClass(verdict: string): string {
  if (verdict === 'TRUSTED') return 'pass';
  if (verdict === 'BLOCKED') return 'fail';
  return 'muted';
}

export default function ReleaseSummary(
  { runId, compareId }: { runId: string; compareId: string | null },
) {
  const [state, setState] = useState<ViewState>({ status: 'loading' });
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    let live = true;
    void Promise.resolve().then(() => { if (live) { setState({ status: 'loading' }); setCopied(false); } });
    const url = `ui/release/${encodeURIComponent(runId)}`
      + (compareId ? `?compare=${encodeURIComponent(compareId)}` : '');
    apiRequest(url).then(
      env => {
        if (!live) return;
        if (!env.up) {
          setState({ status: 'error', message: env.hint ?? 'Backend is offline.' });
          return;
        }
        if (env.status !== 200 || !isView(env.data)) {
          setState({
            status: 'error',
            message: env.status === 404
              ? `Unknown run: ${runId}`
              : `Backend HTTP ${env.status ?? '???'} or unexpected shape.`,
          });
          return;
        }
        setState({ status: 'ready', view: env.data });
      },
      () => {
        if (live) {
          setState({
            status: 'error',
            message: 'Request failed. Is the site dev server still running?',
          });
        }
      },
    );
    return () => { live = false; };
  }, [runId, compareId]);

  async function copyVerify(cmd: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(cmd);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  }

  if (state.status === 'loading') {
    return <p className="mono muted">Loading release brief...</p>;
  }
  if (state.status === 'error') {
    return <p className="mono fail" role="alert">{state.message}</p>;
  }
  const view = state.view;
  return <div className="lab-shell release-summary">
    <div className="release-actions"><button className="button secondary" onClick={() => downloadJson('release-brief.json', view)}><ArrowDownToLine size={15} />Download brief</button><button className="button secondary" onClick={() => window.print()}><Printer size={15} />Print review</button></div>
    <div className="lab-topbar">
      <span className="mono"><span className={verdictClass(view.verdict)}>{view.verdict}</span>
        {' '}{view.verdict_plain}</span>
      <span className="mono muted">{view.run_id}</span>
    </div>
    <div className="lab-results">
      <p style={{ marginTop: 0 }}><strong>{view.headline}</strong></p>
      <p className="mono muted" style={{ fontSize: 11 }}>{view.scope}</p>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
        {view.chips.map(chip => (
          <span key={chip.label} className="mono"
            style={{ border: '1px solid var(--line)', borderRadius: 3, padding: '2px 8px' }}>
            {chip.label}</span>
        ))}
      </div>
      <h3 className="mono muted" style={{ fontSize: 11 }}>REASONS</h3>
      <ul style={{ marginTop: 4, paddingLeft: 18 }}>
        {view.reasons.map(reason => (
          <li key={reason.gate} style={{ marginBottom: 6 }}>
            <span className="mono">{reason.gate} [{reason.band}]</span>
            {' '}{reason.plain_text}{' '}
            <span className="mono muted" style={{ fontSize: 10 }}>{reason.evidence_ref}</span>
          </li>
        ))}
      </ul>
      {view.what_would_change.length > 0 && <>
        <h3 className="mono muted" style={{ fontSize: 11 }}>Review requirements</h3>
        <ul style={{ marginTop: 4, paddingLeft: 18 }}>
          {view.what_would_change.map(line => <li key={line.gate}>{line.move}</li>)}
        </ul>
      </>}
      {view.deltas.length > 0 && <>
        <h3 className="mono muted" style={{ fontSize: 11 }}>
          VS {view.compare_id ?? 'PREVIOUS'}</h3>
        <table className="mono" style={{ fontSize: 11, borderCollapse: 'collapse' }}>
          <thead><tr>
            <th style={{ textAlign: 'left', padding: '4px 12px 4px 0' }}>gate</th>
            <th style={{ textAlign: 'left', padding: '4px 12px 4px 0' }}>from</th>
            <th style={{ textAlign: 'left', padding: '4px 12px 4px 0' }}>to</th>
            <th style={{ textAlign: 'left', padding: '4px 12px 4px 0' }}>delta</th>
            <th style={{ textAlign: 'left', padding: '4px 12px 4px 0' }}>flag</th>
          </tr></thead>
          <tbody>
            {view.deltas.map(d => (
              <tr key={d.gate}>
                <td style={{ padding: '4px 12px 4px 0' }}>{d.gate}</td>
                <td style={{ padding: '4px 12px 4px 0' }}>{d.band_from ?? 'new'}</td>
                <td style={{ padding: '4px 12px 4px 0' }}>{d.band_to}</td>
                <td style={{ padding: '4px 12px 4px 0' }}>
                  {typeof d.delta === 'number' ? d.delta.toFixed(4) : 'n/a'}</td>
                <td style={{ padding: '4px 12px 4px 0' }}>
                  {d.regression ? <span className="fail">REGRESSION</span>
                    : <span className="muted">-</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </>}
      <h3 className="mono muted" style={{ fontSize: 11 }}>VERIFY OFFLINE</h3>
      <pre className="mono"
        style={{ fontSize: 11, background: '#0b0f0e', border: '1px solid var(--line)', borderRadius: 4, padding: 12, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
        {view.offline_verify.command} {'# par_sha256='}{view.offline_verify.hash ?? 'not recorded; compile a dossier first'}</pre>
      <button className="button secondary"
        onClick={() => void copyVerify(view.offline_verify.command)}>
        <Copy size={14} />{copied ? 'Copied' : 'Copy verify command'}</button>
      <p className="mono muted" style={{ fontSize: 10, marginBottom: 0 }}>
        model {view.model_hash ?? 'not recorded'} | operating envelope {view.odd ?? 'not recorded'}</p>
    </div>
  </div>;
}
